import 'package:flutter/material.dart';
import '../services/api_service.dart';
import '../services/auth_service.dart';

class LoginScreen extends StatefulWidget { final AuthService auth; const LoginScreen({super.key, required this.auth}); @override State<LoginScreen> createState() => _LoginScreenState(); }
class _LoginScreenState extends State<LoginScreen> {
  final _form = GlobalKey<FormState>(); final _username = TextEditingController(); final _password = TextEditingController(); bool _busy = false; bool _hide = true; String? _error;
  @override void dispose() { _username.dispose(); _password.dispose(); super.dispose(); }
  Future<void> _submit() async { if (!_form.currentState!.validate()) return; setState(() { _busy = true; _error = null; }); try { await widget.auth.login(_username.text, _password.text); } on ApiException catch (e) { if (mounted) setState(() => _error = e.message); } finally { if (mounted) setState(() => _busy = false); } }
  @override Widget build(BuildContext context) => Scaffold(body: Center(child: ConstrainedBox(constraints: const BoxConstraints(maxWidth: 420), child: Card(child: Padding(padding: const EdgeInsets.all(28), child: Form(key: _form, child: Column(mainAxisSize: MainAxisSize.min, children: [const Icon(Icons.local_parking, size: 64), const SizedBox(height: 12), Text('Parqueo Jasmyn', style: Theme.of(context).textTheme.headlineSmall), const SizedBox(height: 24), TextFormField(controller: _username, decoration: const InputDecoration(labelText: 'Usuario'), validator: (v) => v == null || v.trim().isEmpty ? 'Escriba el usuario.' : null), const SizedBox(height: 12), TextFormField(controller: _password, obscureText: _hide, decoration: InputDecoration(labelText: 'Contraseña', suffixIcon: IconButton(onPressed: () => setState(() => _hide = !_hide), icon: Icon(_hide ? Icons.visibility : Icons.visibility_off))), validator: (v) => v == null || v.isEmpty ? 'Escriba la contraseña.' : null, onFieldSubmitted: (_) => _submit()), if (_error != null) Padding(padding: const EdgeInsets.only(top: 16), child: Text(_error!, style: TextStyle(color: Theme.of(context).colorScheme.error))), const SizedBox(height: 24), FilledButton.icon(onPressed: _busy ? null : _submit, icon: _busy ? const SizedBox.square(dimension: 18, child: CircularProgressIndicator(strokeWidth: 2)) : const Icon(Icons.login), label: Text(_busy ? 'Ingresando...' : 'Ingresar'))])))))));
}
